// Üretilen dosya: tool/ozgun/uret.py. Genel Kültür · Dinler tarihi ve inanç gelenekleri (tarafsız, bilgi düzeyinde) (kolay).
const ozCulture7Kolay = <(String, String, List<String>, String)>[
  ('Bir öğrenci, incelediği bir inancın \'Tanrı birdir, ondan başka tanrı yoktur\' ilkesine dayandığını not ediyor. Bu inanç hangi sınıfa girer?', 'Monoteizm', ['Politeizm', 'Animizm', 'Panteizm'], 'Monoteizm (tektanrıcılık) tek bir tanrının varlığını kabul eder; politeizm ise birden çok tanrıya inanmaktır.'),
  ('Bir antropolog, ziyaret ettiği köyde insanların ırmağın, yaşlı ağacın ve büyük kayanın birer ruhu olduğuna inandığını ve onlardan izin istediğini gözlemliyor. Bu inanç biçimi din biliminde nasıl adlandırılır?', 'Animizm', ['Deizm', 'Agnostisizm', 'Monizm'], 'Animizm, Latince \'anima\' (ruh) sözcüğünden gelir ve doğadaki varlıkların ruh taşıdığı inancını anlatır.'),
  ('Bir klanın üyeleri kartalı ataları sayıyor, onun etini yemiyor ve simgesini tören direklerine oyuyor. Bu uygulama din biliminde hangi kavramla açıklanır?', 'Totemizm', ['Fetişizm', 'Natürizm', 'Henoteizm'], 'Totemizm, klanın kendini bir hayvan ya da bitkiyle (totem) akraba sayması ve ona özel saygı göstermesidir.'),
  ('18. yüzyılda yaşamış bir düşünür, Tanrı\'yı evreni kurup kendi hâline bırakan bir saatçiye benzetiyor ve vahyi kabul etmiyor. Bu düşünürün görüşü hangisidir?', 'Deizm', ['Teizm', 'Panteizm', 'Ateizm'], 'Deizm, Tanrı\'yı yaratıcı olarak kabul eder ama vahyi ve Tanrı\'nın evrene sürekli müdahalesini reddeder; 17-18. yüzyıl Avrupa\'sında yaygınlaşmıştır.'),
  ('Bir kişi \'Tanrı\'nın var olduğunu da olmadığını da kanıtlayamayız; bu konuda kesin bilgiye ulaşmak mümkün değil.\' diyor. Bu kişinin tutumu hangisidir?', 'Agnostisizm', ['Ateizm', 'Deizm', 'Gnostisizm'], 'Agnostisizm, Tanrı\'nın varlığı ya da yokluğu konusunda kesin bilgiye ulaşılamayacağını savunur; terimi 19. yüzyılda Thomas Huxley yaygınlaştırmıştır.'),
  ('Bir dinin öğretisine göre evrenin tarihi, ışık ve iyilik ilkesi ile karanlık ve kötülük ilkesi arasındaki bir savaştır. Bu öğreti hangi anlayışa örnektir?', 'Düalizm', ['Monizm', 'Panteizm', 'Totemizm'], 'Düalizm (ikicilik), iyi ve kötü gibi iki temel ilkeyi kabul eder; Zerdüştlük ve Maniheizm bu anlayışın bilinen örnekleridir.'),
  ('Atalara tapınma anlayışına ilişkin en doğru açıklama hangisidir?', 'Ölmüş ataların ruhlarına saygı gösterip onlara sunu sunmak', ['Yalnız peygamberlerin mezarlarını ziyaret etmek', 'Yeryüzündeki her nesneyi tek bir tanrının parçası sayıp ona tapınmak', 'Yaşayan en yaşlı aile üyesini din adamı ilan etmek'], 'Atalara tapınma (ata kültü), ölmüş ataların ruhlarının yaşayanlarla bağının sürdüğüne inanılarak onlara saygı ve sunu sunulmasıdır; Çin ve Afrika geleneklerinde yaygındır.'),
  ('Bir araştırmacı, aynı dinin farklı ülkelerdeki uygulamalarını yerinde gözlemleyip insanlarla görüşerek veri topluyor. Bu araştırmacının kullandığı yöntem hangisidir?', 'Etnografik alan araştırması', ['Metin eleştirisi', 'Arkeolojik kazı', 'Tarihsel dil karşılaştırması'], 'İnsanları kendi ortamlarında gözlemleyip görüşerek veri toplamak etnografik alan araştırmasıdır; din antropolojisinin temel yöntemidir.'),
  ('Yahudilik, Hristiyanlık ve İslam\'ın ortak atası sayıldığı için bu üç dine birlikte verilen ad hangisidir?', 'İbrahimî dinler', ['Hint kökenli dinler', 'Uzak Doğu dinleri', 'Gizem dinleri'], 'Üç din de soy ve inanç bakımından Hz. İbrahim\'i (Abraham) ortak ata kabul ettiği için \'İbrahimî dinler\' olarak anılır.'),
  ('Yakup peygambere verilen ve sonradan on iki kabileden oluşan halkın adı olan lakap hangisidir?', 'İsrail', ['Yehuda', 'Levi', 'Sion'], 'Tevrat anlatısına göre Yakup\'a \'İsrail\' adı verilmiş, onun on iki oğlundan İsrailoğullarının on iki kabilesi türemiştir.'),
  ('Musa peygamberin Tanrı\'dan On Emir\'i aldığı anlatılan dağ hangisidir?', 'Sina Dağı', ['Ağrı Dağı', 'Zeytin Dağı', 'Karmel Dağı'], 'Tevrat\'taki Çıkış kitabına göre Musa On Emir\'i Sina (Horeb) Dağı\'nda almıştır; Kur\'an\'da bu dağ Tur olarak geçer.'),
  ('Hristiyan geleneğinde İsa\'yı Ürdün Nehri\'nde vaftiz ettiği anlatılan ve İslam\'da da peygamber kabul edilen kişi kimdir?', 'Vaftizci Yahya', ['Havari Petrus', 'Aziz Pavlus', 'Kâhin Zekeriya'], 'Yeni Ahit\'e göre İsa\'yı vaftiz eden Vaftizci Yahya\'dır (Yohanna); İslam\'da Yahya peygamber olarak anılır ve babası Zekeriya\'dır.'),
  ('Kur\'an\'da adıyla bir sure bulunan ve adı geçen tek kadın kim olarak bilinir?', 'Hz. Meryem', ['Hz. Havva', 'Hz. Hatice', 'Hz. Asiye'], 'Meryem, Kur\'an\'da adı açıkça geçen tek kadındır ve 19. sure onun adını taşır.'),
  ('Davud peygambere verildiği kabul edilen kutsal kitap hangisidir?', 'Zebur', ['Tevrat', 'İncil', 'Talmud'], 'İslam geleneğinde Zebur Davud\'a indirilmiş kitap sayılır; Yahudi-Hristiyan geleneğinde bu metin Mezmurlar kitabına karşılık gelir.'),
  ('Tora (Tevrat) dar anlamda kaç kitaptan oluşur?', 'Beş', ['Yedi', 'On iki', 'Dört'], 'Tora, Tekvin, Çıkış, Levililer, Sayılar ve Tesniye\'den oluşan beş kitaptır; bu yüzden Yunanca \'Pentateuk\' (beş kitap) diye de anılır.'),
  ('Bir sinagogda dua eden erkeklerin başlarında küçük, yuvarlak takkeler olduğunu gören bir ziyaretçi bu takkenin adını soruyor. Doğru yanıt hangisidir?', 'Kipa', ['Tallit', 'Tefilin', 'Mezuza'], 'Kipa (Yidişçe yarmulke), Tanrı\'ya saygının simgesi olarak takılan küçük takkedir.'),
  ('İstanbul\'da bir Yahudi ailesini ziyaret eden bir öğrenci, giriş kapısının sağ pervazına eğik olarak tutturulmuş küçük bir kutu görüyor; ev sahibi içinde Şema yazılı bir parşömen olduğunu söylüyor. Bu nesne nedir?', 'Mezuza', ['Menora', 'Tefilin', 'Kipa'], 'Mezuza, Tesniye\'deki \'bu sözleri evinin kapı sövelerine yaz\' buyruğuna dayanır; içindeki parşömende Şema metni bulunur.'),
  ('Antik Kudüs Mabedi\'nde bulunduğu anlatılan ve bugün Yahudiliğin en eski simgelerinden sayılan yedi kollu kandilin adı nedir?', 'Menora', ['Hanukiya', 'Mezuza', 'Şofar'], 'Menora yedi kollu şamdandır; Hanuka\'da kullanılan dokuz kollu şamdan ise hanukiya olarak ayrılır.'),
  ('Bir Yahudi aile Şabat yemeği için hazırlıklarını, mumların yakılacağı vakte yetişecek biçimde tamamlamak istiyor. Şabat geleneksel olarak ne zaman başlar ve ne zaman sona erer?', 'Cuma gün batımından cumartesi akşamına kadar', ['Cumartesi sabahından pazar sabahına kadar', 'Pazar gün doğumundan pazar gece yarısına kadar', 'Cuma öğleninden cumartesi öğlenine kadar'], 'Yahudi geleneğinde gün akşamla başladığından Şabat cuma gün batımında başlar, cumartesi akşamı yıldızlar görününce sona erer.'),
  ('Ortodoks Yahudi bir aile Şabat günü evde ışığı yakıp söndürmek yerine önceden ayarlanmış zamanlayıcı kullanıyor. Bu uygulamanın dinî gerekçesi nedir?', 'Şabat\'ta ateş yakmak dahil yasaklanan işlerden kaçınmak', ['Şabat\'ta evin tamamen karanlık kalmasının zorunlu olması', 'Elektriğin kutsal sayılması', 'Şabat\'ta misafir kabul etmenin yasak olması'], 'Geleneksel yoruma göre Şabat\'ta yapılması yasak 39 iş türü arasında ateş yakmak da vardır; birçok Ortodoks Yahudi elektrik düğmesine basmayı da buna benzetir.'),
  ('New York\'ta bir restoranın kapısında, mutfağın Yahudi beslenme kurallarına uygun olduğunu belirten bir belge asılı. Bu belge restoranı hangi nitelikle tanımlar?', 'Koşer', ['Helal', 'Treyf', 'Parve'], 'Koşer, Yahudi beslenme kurallarına (kaşrut) uygun yiyecektir; uygun olmayana treyf denir.'),
  ('Kaşrut kurallarına göre aşağıdaki öğünlerden hangisi koşer sayılmaz?', 'Kuzu etiyle yoğurt sosunun aynı tabakta yenmesi', ['Pulları ve yüzgeçleri olan balığın yenmesi', 'Usulüne göre kesilmiş tavuğun yenmesi', 'Meyve, sebze ve zeytinyağından oluşan bir salatanın yenmesi'], 'Kaşrut, et ile süt ürünlerinin birlikte pişirilip yenmesini yasaklar; pullu ve yüzgeçli balık, uygun kesilmiş kümes hayvanı ve sebzeler serbesttir.'),
  ('Bir Yahudi aile, oğulları 13 yaşına girdiğinde sinagogda onun ilk kez Tora\'dan okuyacağı ve dinî yükümlülüklere gireceği bir tören düzenliyor. Bu törenin adı ve yapıldığı yaş hangisidir?', 'Bar mitzva, 13 yaş', ['Brit mila, 8 yaş', 'Bat mitzva, 18 yaşında', 'Bar mitzva, 7 yaş'], 'Bar mitzva (\'emrin oğlu\') erkek çocuğun 13 yaşında dinî yükümlülüklere girmesini kutlar; kızlar için bat mitzva genellikle 12 yaşında yapılır.'),
  ('Babasının cenazesinden dönen bir Yahudi kadın, yedi gün boyunca evinde alçak bir taburede oturup taziyeleri kabul ediyor ve aynalar örtülü tutuluyor. Bu yas döneminin adı nedir?', 'Şiva', ['Kadiş', 'Minyan', 'Mitzva'], 'Şiva (İbranice \'yedi\'), cenazenin ardından yakınların evde oturup taziye kabul ettiği yedi günlük yas dönemidir.'),
  ('Orta ve Doğu Avrupa kökenli Yahudilere ne ad verilir?', 'Aşkenaz', ['Seferad', 'Mizrahi', 'Karay'], 'Aşkenaz Yahudileri Orta ve Doğu Avrupa kökenlidir ve geleneksel olarak Yidiş konuşmuştur.'),
  ('1492\'de İspanya\'dan sürülüp bir kısmı Osmanlı topraklarına yerleşen Yahudi topluluğu hangi adla anılır?', 'Seferad Yahudileri', ['Aşkenaz Yahudileri', 'Hasidik Yahudi toplulukları', 'Karay Yahudileri'], 'Seferad (İbranice \'İspanya\') Yahudileri 1492 Elhamra Fermanı ile sürülmüş, II. Bayezid döneminde Osmanlı topraklarına yerleşmiştir.'),
  ('Kral Süleyman\'ın yaptırdığı anlatılan Birinci Mabet hangi devletin saldırısıyla MÖ 587/586\'da yıkılmıştır?', 'Babil', ['Roma', 'Pers', 'Mısır'], 'Birinci Mabet, Nebukadnezar komutasındaki Babil ordusu tarafından yıkılmış ve Yahudilerin bir bölümü Babil\'e sürülmüştür.'),
  ('İkinci Mabet MS 70\'te hangi olay sırasında yıkılmıştır?', 'Romalıların Yahudi isyanını bastırması', ['Babil\'in Kudüs\'ü kuşatması', 'Haçlıların Kudüs\'ü alması', 'Selevkos ordusunun Kudüs seferi'], 'Birinci Yahudi-Roma Savaşı sırasında Titus komutasındaki Roma ordusu MS 70\'te Kudüs\'ü alıp İkinci Mabet\'i yıkmıştır.'),
  ('Bir halkın büyük bir bölümünün anayurdu dışında, farklı ülkelerde dağınık olarak yaşaması durumunu anlatan ve ilk kez Yahudiler için kullanılan terim hangisidir?', 'Diaspora', ['Getto', 'Eksodus', 'Siyon'], 'Diaspora \'dağılma\' demektir; özellikle Babil sürgünü ve Roma döneminden sonra Yahudilerin dağınık yaşamını anlatır, bugün başka halklar için de kullanılır.'),
  ('Yeni Ahit\'te yer alan dört kanonik İncil hangi yazarlara atfedilir?', 'Matta, Markos, Luka, Yuhanna', ['Petrus, Pavlus, Yakup, Yahuda', 'Matta, Tomas, Filipus, Petrus', 'Markos, Luka, Pavlus, Barnaba'], 'Kilisenin kabul ettiği dört İncil Matta, Markos, Luka ve Yuhanna\'ya atfedilir; Tomas İncili gibi metinler kanona alınmamıştır.'),
  ('Yeni Ahit kaç kitaptan oluşur?', '27', ['66', '39', '12'], 'Yeni Ahit 4 İncil, Elçilerin İşleri, 21 mektup ve Vahiy kitabı olmak üzere 27 kitaptan oluşur.'),
  ('Yeni Ahit\'in son kitabı olan ve dünyanın sonuna ilişkin simgesel görümler içeren metin hangisidir?', 'Vahiy', ['Elçilerin İşleri kitabı', 'Romalılara Mektup', 'Mezmurlar'], 'Yuhanna\'ya atfedilen Vahiy kitabı, simgelerle dolu kıyamet görümlerini anlatır ve Yeni Ahit\'i kapatır.'),
  ('Yeni Ahit metinlerinin özgün olarak yazıldığı dil hangisidir?', 'Koine Yunanca', ['Klasik Latince', 'İbranice', 'Süryanice'], 'Yeni Ahit, Doğu Akdeniz\'in ortak dili olan Koine Yunancasıyla yazılmıştır; İsa\'nın gündelik dilinin ise Aramice olduğu kabul edilir.'),
  ('Tarsuslu olan, önce Hristiyanlara karşı çıkıp sonra Şam yolunda yaşadığı deneyimle Hristiyanlığı yaymaya başlayan ve birçok mektubu Yeni Ahit\'e giren kişi kimdir?', 'Pavlus', ['Petrus', 'Barnaba', 'Stefanos'], 'Tarsuslu Saul, Şam yolundaki deneyiminden sonra Pavlus adıyla tanınmış, Anadolu ve Yunanistan\'da gezip kiliseler kurmuş ve mektuplar yazmıştır.'),
  ('Yeni Ahit\'e göre İsa\'nın on iki havarisinden biri olup Roma\'da öldürüldüğüne inanılan ve Katolik gelenekte ilk papa sayılan kişi kimdir?', 'Petrus', ['Pavlus', 'Yuhanna', 'Andreas'], 'Katolik geleneğe göre İsa\'nın \'kaya\' dediği Petrus Roma\'nın ilk piskoposudur; papalar onun halefi sayılır.'),
  ('İsa\'nın tutuklanmasına yol açtığı anlatılan ve bu nedenle Batı dillerinde \'hain\' anlamında kullanılan havari kimdir?', 'Yahuda İskariyot', ['Tomas', 'Matta', 'Filipus'], 'İnciller, Yahuda İskariyot\'un otuz gümüş karşılığında İsa\'yı ele verdiğini anlatır; adı bu yüzden ihanetin simgesi olmuştur.'),
  ('İsa\'nın tepedeki bir konuşmasında \'Ne mutlu yüreği temiz olanlara\' gibi sözlerin yer aldığı ünlü vaazı hangi adla bilinir?', 'Dağdaki Vaaz', ['Son Akşam Yemeği', 'Zeytin Dağı Görümü', 'Kana Düğünü'], 'Matta İncili\'nin 5-7. bölümlerindeki Dağdaki Vaaz, \'Ne mutlu\' ile başlayan sözleri (Beatitudes) ve Rabbin Duası\'nı içerir.'),
  ('Bir Hristiyan, İncillere göre İsa\'nın öğrencilerine öğrettiği ve \'Göklerdeki Babamız, adın kutsal kılınsın\' diye başlayan duayı okuyor. Bu duanın adı nedir?', 'Rabbin Duası', ['Ave Maria', 'Nicea İnanç Bildirgesi', 'Magnificat'], 'Rabbin Duası, İncillere göre İsa\'nın öğrencilerine öğrettiği duadır; Latincede ilk sözcükleri olan \'Pater Noster\' adıyla da anılır.'),
  ('Bir kilisede vaftiz sırasında rahip \'Baba, Oğul ve Kutsal Ruh adına\' sözlerini söylüyor. Bu formül Hristiyanlığın hangi temel öğretisini yansıtır?', 'Teslis', ['Enkarnasyon', 'Kefaret', 'Eskatoloji'], 'Teslis (Trinity) öğretisi, tek Tanrı\'nın Baba, Oğul ve Kutsal Ruh olarak üç kişide var olduğunu kabul eder ve 4. yüzyıl konsillerinde netleşmiştir.'),
  ('325\'te İmparator I. Konstantin\'in çağrısıyla İznik\'te toplanan ilk ekümenik konsilin en önemli gündemi neydi?', 'İsa\'nın Baba ile aynı özden olmadığını savunan Arius\'un görüşleri', ['Papanın yanılmazlığı', 'Protestanlığa karşı alınacak önlemler', 'İkonaların kiliselerde kullanılmasının tamamen yasaklanması'], 'İznik Konsili, İsa\'nın yaratılmış olduğunu savunan İskenderiyeli Arius\'un görüşlerini mahkûm etmiş ve Oğul\'un Baba ile aynı özden olduğunu ilan etmiştir.'),
  ('Katolik Kilisesi\'nin Protestan Reformu\'na yanıt olarak 1545-1563 arasında topladığı konsil hangisidir?', 'Trento Konsili', ['İznik Konsili', 'I. Vatikan Konsili', 'Konstanz Konsili'], 'Trento Konsili, Katolik öğretiyi yeniden tanımlamış ve Karşı Reform\'un temelini oluşturmuştur.'),
  ('Hristiyanlığın Roma İmparatorluğu\'nda serbest bırakılmasını sağlayan 313 tarihli düzenleme hangisidir?', 'Milano Fermanı', ['Vormus Fermanı', 'Nant Fermanı', 'Selanik Fermanı'], 'I. Konstantin ve Licinius\'un 313 Milano Fermanı, Hristiyanlara ve diğer inançlara ibadet özgürlüğü tanımıştır.'),
  ('Hristiyan dünyasının Katolik ve Ortodoks olarak iki büyük kola ayrılması genellikle hangi yıla tarihlenir?', '1054', ['1453', '1204', '1517'], '1054\'te Roma ve İstanbul kiliselerinin temsilcileri birbirini aforoz etmiş; bu olay Büyük Ayrılık (Şizma) olarak anılır.'),
  ('Ortodoks dünyasında \'eşitler arasında birinci\' sayılan ve Fener\'de bulunan makam hangisidir?', 'İstanbul Ekümenik Patrikliği', ['Moskova Patrikliği', 'İskenderiye Rum Ortodoks Patrikliği', 'Atina Başpiskoposluğu'], 'Fener Rum Patrikhanesi\'ndeki Ekümenik Patrik, Ortodoks kiliseler arasında onur bakımından birinci sayılır; ancak Katolik papası gibi tüm kiliseler üzerinde yetkisi yoktur.'),
  ('1517\'de Wittenberg\'de 95 Tez\'i yayımlayarak Reform hareketini başlatan kişi kimdir?', 'Martin Luther', ['Jean Calvin', 'Ulrich Zwingli', 'Jan Hus'], 'Alman rahip Martin Luther\'in endüljans satışını eleştiren 95 Tez\'i Protestan Reformu\'nun başlangıcı sayılır.'),
  ('Martin Luther\'in 95 Tez\'de özellikle eleştirdiği uygulama hangisidir?', 'Endüljans denen bağışlanma belgelerinin satılması', ['Kiliselerde orgla müzik yapılması', 'Kutsal Kitap\'ın Almancaya çevrilmesi', 'Rahiplerin vaaz vermesi'], 'Endüljanslar, kilisenin parayla sattığı ve öbür dünyadaki cezayı hafiflettiği öne sürülen belgelerdi; Luther bunun kurtuluşu satın alınabilir gösterdiğini savunmuştur.'),
  ('Cenevre\'de etkili olan, kader (predestinasyon) öğretisini vurgulayan Fransız asıllı Reformcu kimdir?', 'Jean Calvin', ['Martin Luther', 'John Knox', 'Erasmus'], 'Jean Calvin \'Hristiyan Dininin Esasları\' eserini yazmış, Cenevre\'de etkili olmuş ve Kalvinizm onun adıyla anılmıştır.'),
  ('Bir ibadet toplantısında rahip, kürsü ya da müzik yok; katılımcılar sessizce oturuyor ve içlerinden biri gerek duyduğunda kalkıp kısa bir konuşma yapıyor. Bu ibadet biçimi hangi Protestan topluluğa özgüdür?', 'Kuakerler', ['Anglikanlar', 'Lutherciler', 'Metodistler'], '17. yüzyılda George Fox\'un kurduğu Kuakerler, ruhban sınıfı olmadan sessiz toplantılarda ibadet eder; savaşa karşı tutumlarıyla bilinir.'),
  ('ABD\'de bir kırsal yolda at arabasıyla ilerleyen, sade koyu renk giysiler giymiş, evlerinde elektrik şebekesi kullanmayan bir topluluk görülüyor. Bu topluluk büyük olasılıkla hangisidir?', 'Amişler', ['Mormonlar', 'Kuakerler', 'Adventistler'], 'Amişler, 17. yüzyılda Jakob Ammann\'ın öncülüğünde Mennonitlerden ayrılmış, sade giyim ve sınırlı teknoloji kullanımıyla bilinen bir topluluktur.'),
  ('Vatikan\'da Sistina Şapeli\'nin kapıları kapanıyor; içeride 80 yaşından küçük kardinaller dış dünyayla bağlantısı kesilmiş olarak yeni papa için oy kullanıyor. Bu seçim toplantısına ne ad verilir?', 'Konklav', ['Sinod', 'Konsil', 'Kurya'], 'Konklav, Latince \'anahtarla kilitli\' anlamına gelir; kardinaller Sistina Şapeli\'nde dış dünyayla bağlantısı kesilmiş olarak oy kullanır.'),
  ('Papa seçimi sürerken Sistina Şapeli\'nin bacasından beyaz duman çıkması neyi duyurur?', 'Yeni papanın seçildiğini', ['Oylamanın bir sonraki güne ertelendiğini', 'Kardinallerden birinin hastalandığını ve oylamanın durduğunu', 'Seçimin sonuçsuz kaldığını'], 'Oy pusulaları yakılırken siyah duman sonuçsuz oylamayı, beyaz duman ise yeni papanın seçildiğini bildirir.'),
  ('Katolik Kilisesi\'nde papayı seçme yetkisine sahip olan ve kırmızı giysileriyle tanınan üst düzey din adamlarına ne ad verilir?', 'Kardinal', ['Metropolit', 'Arşidük', 'Diyakoz'], 'Kardinaller papanın danışmanlarıdır; 80 yaşın altındaki kardinaller konklavda oy kullanabilir.'),
  ('Katolik bir genç, inancını kilise önünde onaylamak için piskopostan kutsal yağla mesh edildiği bir törene katılıyor. Bu sakrament hangisidir?', 'Konfirmasyon', ['Vaftiz', 'Hasta yağlama', 'Tövbe'], 'Konfirmasyon (Krizma), vaftizle başlayan Hristiyan kimliğinin onaylanmasıdır; genellikle piskopos tarafından kutsal yağla yapılır.'),
  ('Bir kişinin kilise topluluğundan ve sakramentlerden resmen dışlanması anlamına gelen kilise cezası hangisidir?', 'Aforoz', ['Kanonizasyon', 'Tövbe', 'Konfirmasyon'], 'Aforoz (ekskomünikasyon), kişinin kilise üyeliğinden doğan sakramentlere katılım hakkını kaldıran cezadır; 1054\'te iki kilise birbirini aforoz etmiştir.'),
  ('Katolik bir kadın, elindeki boncuk dizisinin her tanesinde bir dua okuyarak ilerliyor. Bu dua uygulamasının adı nedir?', 'Tespih duası', ['Litürji', 'Vespers', 'Novena'], 'Rosaryo, boncuklu bir tespih yardımıyla Rabbin Duası ve Ave Maria gibi duaların belli bir düzende tekrarıdır.'),
  ('Katolik geleneğinde inananın günahlarını rahibe kapalı bir bölmede söylemesine ne ad verilir?', 'Günah çıkarma', ['Vaftiz', 'Konfirmasyon', 'Ayin alayı'], 'Tövbe sakramentinin parçası olan itirafta kişi günahlarını rahibe söyler; rahip bağışlama duası okur ve itirafı gizli tutmakla yükümlüdür.'),
  ('13. yüzyılda yoksulluğu ve doğa sevgisini öne çıkaran, mülk edinmeyi reddeden dilenci tarikatının kurucusu kimdir?', 'Assisili Francesco', ['Nursialı Benedictus', 'Clairvaux\'lu Bernard', 'Thomas Aquinas'], 'Assisili Francesco\'nun kurduğu Fransiskenler, mutlak yoksulluk ilkesini benimseyen dilenci tarikatlarındandır.'),
  ('Antakya merkezli olup Aramicenin bir lehçesini ayin dili olarak kullanan, Türkiye\'de özellikle Tur Abdin\'de yaşayan Hristiyan topluluk hangisidir?', 'Süryaniler', ['Kıptiler', 'Maruniler', 'Keldaniler'], 'Süryani Ortodoks Kilisesi Süryaniceyi (Aramicenin bir lehçesi) ayin dili olarak kullanır; Mardin\'deki Tur Abdin bölgesi topluluğun tarihî merkezlerindendir.'),
  ('Mısır\'ın yerli Hristiyanlarına verilen ad hangisidir?', 'Kıptiler', ['Maruniler', 'Nasturiler', 'Melkitler'], 'Kıpti Ortodoks Kilisesi, geleneğe göre Markos tarafından kurulan İskenderiye kilisesine dayanır; \'Kıpti\' adı Yunanca \'Mısırlı\' anlamındaki sözcükten gelir.'),
  ('Devlet olarak Hristiyanlığı resmî din kabul eden ilk krallık hangisidir?', 'Ermenistan', ['Roma', 'Etiyopya', 'Gürcistan'], 'Geleneksel tarihe göre Ermeni Kralı III. Tiridates, Aydınlatıcı Grigor\'un etkisiyle 301 civarında Hristiyanlığı devlet dini yapmıştır; Roma\'da bu 380\'de olmuştur.'),
  ('Bir piskoposun resmî makam koltuğunun bulunduğu ana kiliseye ne ad verilir?', 'Katedral', ['Şapel', 'Bazilika', 'Manastır'], 'Katedral adı, Latince \'piskopos koltuğu\' anlamına gelen \'cathedra\' sözcüğünden gelir.'),
  ('Bir havalimanının içinde, yolcuların dua edebilmesi için ayrılmış küçük bir Hristiyan ibadet odası bulunuyor. Böyle küçük ibadet yerlerine ne ad verilir?', 'Şapel', ['Katedral', 'Bazilika', 'Manastır kilisesi'], 'Şapel, büyük bir yapının içinde ya da yanında bulunan küçük ibadet mekânıdır.'),
  ('Kilise planlarında sunağın bulunduğu, genellikle yarım daire biçimli ve doğuya bakan çıkıntıya ne ad verilir?', 'Apsis', ['Nartheks', 'Nef', 'Transept'], 'Apsis, sunağın yer aldığı yarım daire planlı bölümdür; geleneksel kiliselerde çoğunlukla doğuya yönlendirilir.'),
  ('Kilisenin girişten sunağa doğru uzanan, cemaatin bulunduğu ana uzun bölümüne ne ad verilir?', 'Nef', ['Apsis', 'Kripta', 'Nartheks'], 'Nef, Latince \'gemi\' anlamındaki navis sözcüğünden gelir ve kilisenin cemaate ayrılan ana gövdesidir.'),
  ('Kur\'an\'ın bölümlerine ne ad verilir ve kaç tanedir?', 'Sure, 114', ['Ayet, 114', 'Cüz, 114', 'Sure, 30'], 'Kur\'an 114 sureden oluşur; Kur\'an ayrıca okuma kolaylığı için yaklaşık eşit 30 cüze bölünmüştür.'),
  ('Kur\'an\'ın ilk suresi olan ve her namazda okunan sure hangisidir?', 'Fatiha', ['Bakara', 'İhlas', 'Yasin'], 'Fatiha \'açılış\' anlamına gelir; Kur\'an\'ı açan bu sure namazın her rekâtında okunur.'),
  ('Kur\'an\'ın en uzun suresi hangisidir?', 'Bakara', ['Al-i İmran', 'Nisa', 'Yasin'], '286 ayetten oluşan Bakara suresi Kur\'an\'ın en uzun suresidir.'),
  ('Bir öğrenci birkaç yıllık çalışmayla Kur\'an\'ın 114 suresinin tamamını ezbere okuyabilir hâle geliyor. Bu öğrenciye ne unvan verilir?', 'Hafız', ['Müezzin', 'Müftü', 'Kur’an kâtibi'], 'Hafız, Kur\'an\'ı baştan sona ezberlemiş kişidir; ezber eğitimi veren yerlere hafızlık kursu denir.'),
  ('Bir âlim, Kur\'an\'ın bir ayetinin hangi olay üzerine indiğini, sözcüklerinin anlamlarını ve farklı yorumlarını ayrıntılı biçimde açıklayan çok ciltli bir eser yazıyor. Bu eser türünün adı nedir?', 'Tefsir', ['Fıkıh', 'Kelam', 'Siyer'], 'Tefsir, Kur\'an\'ın anlamını açıklayan ilimdir; Hz. Muhammed\'in hayatını anlatan eserlere ise siyer denir.'),
  ('İslam\'da Hz. Muhammed\'in sözlerine, davranışlarına ve onaylarına verilen genel ad hangisidir?', 'Sünnet', ['Kıyas', 'İcma', 'Tefsir'], 'Sünnet, Hz. Muhammed\'in söz, fiil ve onaylarının bütünüdür; bunların sözlü aktarımlarına hadis denir.'),
  ('İslam\'da Müslümanların temel ibadet yükümlülükleri olarak sayılan \'İslam\'ın şartları\' kaç tanedir?', 'Beş', ['Üç', 'Yedi', 'On'], 'Sünni gelenekte İslam\'ın beş şartı kelime-i şehadet, namaz, oruç, zekât ve hacdır.'),
  ('İslam\'da belirli bir zenginliğe ulaşan kişinin malının bir bölümünü her yıl ihtiyaç sahiplerine vermesi ibadetine ne ad verilir?', 'Zekât', ['Fitre', 'Kurban', 'Vakıf'], 'Zekât, nisap denen asgari zenginlik ölçüsüne ulaşan kişilerin yılda bir kez malının belli bir oranını vermesidir; altın ve para için bu oran kırkta birdir.'),
  ('Altın, gümüş ve nakit para gibi mallarda zekât oranı geleneksel olarak ne kadardır?', 'Kırkta bir (yüzde 2,5)', ['Onda bir (yüzde 10)', 'Beşte bir (yüzde 20)', 'Yüzde bir'], 'Para ve altın gibi birikimlerde zekât, bir yıl elde kalan miktarın kırkta biridir; bu da yüzde 2,5\'e karşılık gelir.'),
  ('Birikiminde zekâta tabi 80.000 lira bir yıl boyunca kalan bir kişi, kırkta bir oranına göre kaç lira zekât vermelidir?', '2.000', ['8.000', '4.000', '1.600'], 'Kırkta bir oranı 80.000 / 40 = 2.000 lira eder (yüzde 2,5).'),
  ('Ramazan ayında, bayramdan önce verilmesi gereken ve kişi başına belirlenen sadakaya ne ad verilir?', 'Fitre', ['Zekât', 'Kefaret', 'Adak'], 'Fitre, Ramazan Bayramı\'ndan önce imkânı olanların ailedeki her kişi için verdiği sadakadır.'),
  ('İslam\'da oruç tutan bir kişi gün boyunca neyden kaçınır?', 'İmsaktan iftara kadar yemek, içmek ve cinsel ilişkiden', ['Yalnız gece yarısından öğlene kadar et yemekten', 'Yalnız iftardan sahura kadar konuşmaktan ve uyumaktan', 'Sabahtan akşama yalnız su içmekten'], 'Oruçta imsak vaktinden akşam ezanına (iftar) kadar yeme, içme ve cinsel ilişkiden uzak durulur.'),
  ('İslam\'da vahyi peygamberlere ileten melek olarak bilinen melek hangisidir?', 'Cebrail', ['Mikail', 'İsrafil', 'Azrail'], 'Cebrail vahiy meleğidir; İslam geleneğinde Mikail doğa olaylarıyla, İsrafil sura üflemekle, Azrail can almakla görevli sayılır.'),
  ('İslam inancında kıyametin kopması ve yeniden dirilişle ilişkilendirilen \'sur\'a üfleyecek melek kimdir?', 'İsrafil', ['Cebrail', 'Mikail', 'Münker'], 'İslam geleneğinde İsrafil, kıyamet ve diriliş için sura üfleyecek melektir.'),
  ('Bir kişi namaza durmadan önce sırasıyla ellerini, ağzını, burnunu, yüzünü ve kollarını yıkıyor, başını meshedip ayaklarını yıkıyor. Bu kişi ne yapmaktadır?', 'Abdest', ['Gusül', 'Teyemmüm', 'Tavaf'], 'Abdest, el, ağız, burun, yüz, kollar, baş ve ayakların belli bir düzende yıkanması ya da meshedilmesidir; tüm bedenin yıkanmasına gusül denir.'),
  ('Çölde yolculuk eden ve yanında hiç su olmayan bir Müslüman, namaz vakti girince ellerini temiz toprağa vurup yüzünü ve kollarını meshediyor. Bu uygulamanın adı nedir?', 'Teyemmüm', ['Gusül', 'Mesh', 'İstinca'], 'Teyemmüm, suyun bulunmadığı ya da sağlık nedeniyle kullanılamadığı durumlarda temiz toprak ya da toprak cinsinden bir yüzeyle yapılan temizliktir.'),
  ('Günlük beş vakit namaz doğru sırayla hangisinde verilmiştir?', 'Sabah, öğle, ikindi, akşam, yatsı', ['Sabah, ikindi, öğle, yatsı, akşam', 'Öğle, sabah, akşam, ikindi, yatsı', 'Sabah, öğle, akşam, ikindi, yatsı'], 'Beş vakit namaz gün içinde sabah, öğle, ikindi, akşam ve yatsı sırasıyla kılınır.'),
  ('Namazın ayakta durma, rükû ve secdelerden oluşan her bir birimine ne ad verilir?', 'Rekât', ['Vakit', 'Kıyam', 'Selam'], 'Rekât, namazın bir kıyam, bir rükû ve iki secdeden oluşan birimidir; örneğin sabah namazının farzı iki rekâttır.'),
  ('Cuma namazına giden bir kişi, farz namazdan önce imamın minbere çıkıp Arapça ve Türkçe bölümleri olan bir konuşma yaptığını dinliyor. Bu konuşmanın adı nedir?', 'Hutbe', ['Vaaz', 'Mevlit', 'Kamet'], 'Hutbe, cuma ve bayram namazlarında minberde okunan, namazın parçası sayılan konuşmadır; namaz dışında kürsüde yapılan öğütlere vaaz denir.'),
  ('Camilerde imamın cuma hutbesini okumak için çıktığı, merdivenli yüksek yere ne ad verilir?', 'Minber', ['Mihrap', 'Kürsü', 'Mahfil'], 'Minber, cuma ve bayram hutbelerinin okunduğu merdivenli yükseltidir; vaazlar ise genellikle kürsüde verilir.'),
  ('Cami avlusunda abdest almak için yapılmış, genellikle çok musluklu ve üstü örtülü yapıya ne ad verilir?', 'Şadırvan', ['Sebil', 'Çeşme', 'Hazire'], 'Şadırvan, cami avlularında abdest alınması için yapılan çevresi musluklu havuz ya da yapıdır.'),
  ('Mekke\'ye umreye giden bir erkek, belirlenmiş sınıra (mikat) varmadan önce dikişsiz iki parça beyaz örtüye bürünüyor ve bu sırada saçını kesmek, koku sürmek gibi davranışlardan kaçınacağını biliyor. Hacının girdiği bu durumun adı nedir?', 'İhram', ['Tavaf', 'Sa\'y', 'Vakfe'], 'İhram hem hacıların giydiği dikişsiz örtünün hem de bu sırada uyulması gereken yasaklarla belirlenen durumun adıdır.'),
  ('Mekke\'deki bir hacı, Hacerü\'l-Esved köşesinden başlayarak Kâbe\'nin çevresinde yedi kez dönüyor. Hacının yaptığı ibadetin adı nedir?', 'Tavaf', ['Sa\'y', 'Vakfe', 'Remy'], 'Tavaf, Kâbe\'nin çevresinde Hacerü\'l-Esved köşesinden başlayarak yedi kez dönmektir.'),
  ('Hacıların Safa ile Merve tepeleri arasında yedi kez gidip gelmesi hangi anlatıyı anar?', 'Hz. Hacer\'in oğlu İsmail için su araması', ['Hz. İbrahim\'in Kâbe\'yi inşa etmesi', 'Hz. Muhammed\'in Medine\'ye hicreti', 'Nuh tufanından sonra karaya çıkılması'], 'Sa\'y, Hz. Hacer\'in susuz kalan oğlu İsmail için iki tepe arasında su arayarak koşmasını anar; anlatıya göre ardından zemzem suyu çıkmıştır.'),
  ('Bir tarih kitabında \'622 yılında Mekkeli Müslümanlar baskılar nedeniyle yurtlarını bırakıp Yesrib\'e yerleşti\' yazıyor. İslam tarihinde bu olay hangi adla anılır?', 'Hicret', ['Fetih', 'Biat', 'Miraç'], 'Hicret \'göç\' anlamına gelir; 622\'deki Medine\'ye göç İslam tarihinin dönüm noktalarındandır.'),
  ('Hicretten önce Medine\'nin adı neydi?', 'Yesrib', ['Taif', 'Hayber', 'Tebük'], 'Medine\'nin eski adı Yesrib\'dir; hicretten sonra \'Peygamber şehri\' anlamında Medinetü\'n-Nebi, kısaca Medine denmiştir.'),
  ('Medineli bir aile, Mekke\'den yalnız canını kurtarıp gelen bir Müslüman aileye evini ve malını paylaşmayı teklif ediyor. İslam tarihinde göç eden ve onları kabul eden bu iki gruba sırasıyla ne ad verilir?', 'Muhacir ve Ensar', ['Ensar ve Muhacir', 'Sahabe ve Tabiin', 'Hanifler ve Muhacirler'], 'Göç edenlere \'muhacir\', onlara kucak açan Medinelilere \'yardımcılar\' anlamında \'ensar\' denmiştir.'),
  ('Hz. Muhammed\'in vefatından sonra seçilen ilk dört halifeye verilen ortak ad hangisidir?', 'Hulefa-i Raşidin', ['Ashab-ı Kehf', 'Aşere-i Mübeşşere', 'Ehl-i Beyt'], 'Hulefa-i Raşidin, Hz. Ebubekir, Hz. Ömer, Hz. Osman ve Hz. Ali\'den oluşan ilk dört halifedir.'),
  ('İlk dört halife doğru sırayla hangisinde verilmiştir?', 'Ebubekir, Ömer, Osman, Ali', ['Ömer, Ebubekir, Ali, Osman', 'Ebubekir, Osman, Ömer, Ali', 'Ali, Ebubekir, Ömer, Osman'], 'Halifelik sırası Hz. Ebubekir (632-634), Hz. Ömer (634-644), Hz. Osman (644-656) ve Hz. Ali (656-661) şeklindedir.'),
  ('680\'de Hz. Hüseyin ile yakınlarının Emevi ordusuyla karşılaşıp hayatını kaybettiği olay hangi adla bilinir?', 'Kerbela Olayı', ['Cemel Vakası', 'Sıffin Savaşı', 'Hendek Savaşı'], 'Kerbela\'da Hz. Hüseyin ve beraberindekiler Yezid\'in ordusu tarafından öldürülmüştür; olay özellikle Şii ve Alevi geleneğinde derin bir yas olarak anılır.'),
  ('Anadolu Aleviliğinde Kerbela\'da şehit düşenler için Muharrem ayında tutulan yas orucu geleneksel olarak genellikle kaç gün sürer?', 'On iki gün', ['Otuz gün', 'Üç gün', 'Kırk gün'], 'Aleviler Muharrem ayında Kerbela şehitleri ve on iki imam anısına genellikle on iki gün yas tutup oruç tutar; ardından aşure pişirilir.'),
  ('Müslümanların ilk kıblesi neresiydi?', 'Kudüs\'teki Mescid-i Aksa', ['Mekke\'deki Kâbe', 'Medine\'deki Kuba Mescidi', 'Şam\'daki Emevi Camii\'nin bulunduğu yer'], 'Müslümanlar bir süre Kudüs\'e yönelerek namaz kılmış, hicretin ikinci yılında kıble Kâbe olarak değiştirilmiştir.'),
  ('Sünni İslam\'da yaygın olan dört fıkıh mezhebi hangileridir?', 'Hanefi, Şafii, Maliki, Hanbeli', ['Hanefi, Caferi, Maturidi, Eş\'ari', 'Şafii, Mutezile, Zeydi, Maliki', 'Hanbeli, İsmaili, Hanefi, Selefi'], 'Sünni dünyada dört fıkıh (amelî) mezhebi Hanefi, Şafii, Maliki ve Hanbeli\'dir; Maturidilik ve Eş\'arilik ise itikadi mezheplerdir.'),
  ('Türkiye\'de ve Balkanlar\'da Müslümanların büyük çoğunluğunun izlediği fıkıh mezhebi hangisidir ve kurucusu kimdir?', 'Hanefi - İmam-ı Azam Ebu Hanife', ['Şafii - İmam Şafii', 'Maliki - İmam Malik', 'Hanbeli - Ahmed bin Hanbel'], 'Hanefi mezhebi Kûfeli âlim Ebu Hanife\'ye dayanır; Osmanlı\'nın resmî mezhebi olmuş, Türkiye, Balkanlar ve Orta Asya\'da yaygınlaşmıştır.'),
  ('Bir genç, yıllarca bir şeyhin yanında kalıp onun öğütleriyle nefsini terbiye etmeye ve manevi yolda ilerlemeye çalışıyor. Bu gence yol gösteren kişiye tasavvufta ne ad verilir?', 'Mürşit', ['Müezzin', 'Müftü', 'Kadı'], 'Mürşit \'yol gösteren\' demektir; tarikatta müridin manevi eğitiminden sorumlu şeyh ya da rehberdir.'),
  ('Bir tekkede dervişler halka olup \'Allah\' adını ve \'La ilahe illallah\' sözünü uzun süre ritmik biçimde tekrar ediyor. Dervişlerin yaptığı bu ibadetin adı nedir?', 'Zikir', ['Vaaz', 'Hutbe', 'Tefsir'], 'Zikir \'anma\' demektir; tarikatlarda sesli (cehri) ya da sessiz (hafi) zikir uygulanır.'),
  ('Tarikat mensuplarının toplanıp ibadet ve sohbet ettiği, şeyhin bulunduğu mekâna genel olarak ne ad verilir?', 'Tekke', ['Medrese', 'Kervansaray', 'Bedesten'], 'Tekke ve dergâh, tasavvuf ehlinin toplanıp zikir ve sohbet yaptığı yerlerdir; küçüklerine zaviye de denir.'),
  ('Mevleviliğe adını veren ve Mesnevi\'yi yazan şair-düşünür kimdir?', 'Mevlânâ Celaleddin Rumi', ['Yunus Emre', 'Hacı Bektaş-ı Veli', 'Ahmed Yesevi'], 'Mevlevilik, Mevlânâ Celaleddin Rumi\'nin öğretileri üzerine oğlu Sultan Veled tarafından kurumlaştırılmıştır.'),
  ('Bir derviş, şeyhinin izniyle kırk gün boyunca bir hücreye çekilip az yiyerek, az uyuyarak ibadet ve tefekkürle vakit geçiriyor. Dervişin yaşadığı bu dönemin adı nedir?', 'Çile', ['Sema', 'Hırka', 'Biat'], 'Çile (Farsça \'kırk\'), dervişin kırk gün süreyle az yiyip uyuyarak ibadet ve tefekkürle geçirdiği inziva dönemidir.'),
  ('Bir cemevinde dedenin önderliğinde toplanan kadın ve erkekler, bağlama eşliğinde deyişler söylüyor, ardından semah dönüyor ve lokma paylaşıyor. Bu ibadet toplantısının adı nedir?', 'Cem', ['Mevlit', 'Sema', 'Hatim'], 'Cem, Alevi toplumunun dede önderliğinde bir araya geldiği, deyiş, semah ve dualarla yürütülen temel ibadettir; yapıldığı yere cemevi denir.'),
  ('Alevi toplumunda cemleri yöneten ve soyunun Ehl-i Beyt\'e dayandığına inanılan inanç önderine ne ad verilir?', 'Dede', ['Müftü', 'Şeyhülislam', 'Kadı'], 'Alevilikte dedeler ocak denilen soy topluluklarına mensuptur; cemi yönetir, toplumun manevi rehberliğini üstlenir.'),
  ('Alevi geleneğinde iki evli çift cemde ikrar vererek birbirlerinin sevincini, derdini ve sorumluluğunu ömür boyu paylaşacaklarına söz veriyor. Bu yol kardeşliğine ne ad verilir?', 'Musahiplik', ['Hemşerilik', 'Kirvelik', 'Sütkardeşlik'], 'Musahiplik, iki evli çiftin cemde yemin ederek birbirlerinin hem maddi hem manevi sorumluluğunu üstlendiği yol kardeşliğidir.'),
  ('Hacı Bektaş-ı Veli\'nin türbesi ve dergâhı bugün hangi ilde bulunur?', 'Nevşehir', ['Konya', 'Kırşehir', 'Amasya'], 'Hacı Bektaş-ı Veli Dergâhı, Nevşehir\'in Hacıbektaş ilçesindedir; ilçe Cumhuriyet\'in ilk yıllarına kadar Kırşehir\'e bağlıydı.'),
  ('Türkistan\'da yaşamış, Yesevilik tarikatının kurucusu olan ve dörtlüklerine \'hikmet\' denen mutasavvıf kimdir?', 'Ahmed Yesevi', ['Yunus Emre', 'Hacı Bayram-ı Veli', 'Sarı Saltuk'], '12. yüzyılda yaşayan Ahmed Yesevi, Türkçe yazdığı hikmetleriyle İslam\'ı Orta Asya Türkleri arasında yaymıştır; şiirleri \'Divan-ı Hikmet\'te toplanmıştır.'),
  ('Bir din, Musa, İsa, Muhammed ve Buda gibi önderlerin aynı Tanrı\'dan gelen ardışık mesajlar getirdiğini ve insanlığın tek bir aile olduğunu öğretiyor; kurucusu 19. yüzyılda İran\'da doğmuştur. Bu din hangisidir?', 'Bahailik', ['Zerdüştlük', 'Ezidilik', 'Maniheizm'], 'Bahailik, Bahaullah\'ın öğretilerine dayanır; dinlerin ortak kaynağını, insanlığın birliğini ve kadın-erkek eşitliğini vurgular.'),
  ('Zerdüştlükte iyiliğin ve bilgeliğin yüce tanrısına verilen ad hangisidir?', 'Ahura Mazda', ['Ehrimen', 'Mitra', 'Brahma'], 'Ahura Mazda \'Bilge Efendi\' anlamına gelir; Zerdüşt öğretisinde ona karşıt yıkıcı ruh Angra Mainyu\'dur (Ehrimen).'),
  ('Zerdüştlüğün temel ahlak ilkesi olan üçlü öğüt hangisidir?', 'İyi düşünce, iyi söz, iyi iş', ['Oruç, sadaka, dua', 'Doğru görüş, doğru niyet, doğru söz', 'Sevgi, umut, iman'], 'Zerdüştlükte \'humata, hukhta, hvarshta\', yani iyi düşünce, iyi söz ve iyi iş temel ahlak ilkesidir.'),
  ('İslam\'ın İran\'a yayılmasından sonra Hindistan\'a göç ederek bugün özellikle Mumbai\'de yaşayan Zerdüşt topluluğuna ne ad verilir?', 'Parsiler', ['Sihler', 'Caynlar', 'Tamiller'], 'Parsi adı \'Persli\' anlamındadır; 8-10. yüzyıllarda Gujarat kıyılarına göç eden Zerdüştlerin torunlarıdır.'),
  ('8. yüzyılda Maniheizmi devlet dini olarak kabul eden Türk devleti hangisidir?', 'Uygur Kağanlığı', ['Göktürk Kağanlığı', 'Hazar Kağanlığı', 'Karahanlılar'], 'Uygur Kağanı Bögü Kağan 762\'de Maniheizmi kabul etmiş ve bu din Uygurlar arasında resmî din olarak yayılmıştır.'),
  ('Hinduizmin en eski kutsal metinleri olan ve Sanskritçe ilahilerden oluşan dört derleme hangi adla bilinir?', 'Vedalar', ['Upanişadlar', 'Puranalar', 'Sutralar'], 'Rigveda, Samaveda, Yajurveda ve Atharvaveda\'dan oluşan Vedalar Hinduizmin en eski metinleridir; Rigveda\'nın MÖ 1500-1000 arasında oluştuğu düşünülür.'),
  ('Bir Hindu dede torununa \'Bugün yaptığın iyilik ya da kötülük, bu hayatta ya da sonraki hayatlarında karşına çıkacak.\' diyor. Dedenin dayandığı ilke hangisidir?', 'Karma', ['Mokşa', 'Mantra', 'Puja'], 'Karma \'eylem\' demektir; her eylemin ahlaki bir sonucu olduğu ve bu sonucun yeniden doğuşları etkilediği inancını anlatır.'),
  ('Bir Budist metninde varlıkların sürekli doğup ölerek yeni bedenlerde var olmayı sürdürdüğü ve bunun bir çark gibi döndüğü anlatılıyor. Bu döngünün adı nedir?', 'Samsara', ['Nirvana', 'Dharma', 'Ahimsa'], 'Samsara, varlıkların karmalarına göre sürekli yeniden doğduğu döngüdür; bu döngüden kurtuluş Hinduizmde mokşa, Budizmde nirvana diye anılır.'),
  ('Hinduizmde yeniden doğuş döngüsünden kurtulup nihai özgürlüğe ulaşmaya ne ad verilir?', 'Mokşa', ['Karma', 'Samsara', 'Avatar'], 'Mokşa \'kurtuluş, özgürleşme\' anlamına gelir ve Hindu yaşamının dört amacından en yücesi sayılır.'),
  ('Klasik Hindu öğretisine göre öğrencilik, ev sahipliği ve ormana çekilmeden sonra gelen dördüncü yaşam evresi (aşrama) hangisidir?', 'Her şeyden el çekip dolaşan çileci olma (sannyasa)', ['Evlenip aile kurma ve çalışma (grihastha)', 'Bir öğretmenin yanında kutsal metin öğrenme (brahmacharya)', 'Siyasi yönetimde görev alıp savaşa katılma (kşatra)'], 'Klasik düzende dört aşrama brahmacharya (öğrencilik), grihastha (ev sahipliği), vanaprastha (ormana çekilme) ve sannyasa (tümüyle feragat) evreleridir.'),
  ('Bir Hindu tapınağındaki üç yüzlü bir heykel, evrenin yaratılmasını, korunmasını ve yok edilerek yenilenmesini birlikte simgeliyor. Bu üçlü tanrısal anlayışa ne ad verilir?', 'Trimurti', ['Trinity', 'Tripitaka', 'Triratna'], 'Trimurti\'de Brahma yaratıcı, Vişnu koruyucu, Şiva ise yok edici ve dönüştürücü yönü temsil eder.'),
  ('Hindistan\'da yeni bir dükkân açan bir esnafın açılış töreninde önce fil başlı bir tanrının tasvirine çiçek sunduğu görülüyor. Bu tanrı kimdir?', 'Ganeşa', ['Hanuman', 'İndra', 'Agni'], 'Ganeşa, Şiva ile Parvati\'nin oğlu olarak anılır; bilgelik ve başlangıçların tanrısı sayılır ve törenlerde ilk olarak ona dua edilir.'),
  ('Mahabharata destanının bir bölümü olan ve Krişna\'nın savaş alanında Arjuna\'ya ödev ve bağlılık üzerine öğüt verdiği metin hangisidir?', 'Bhagavad Gita', ['Rigveda', 'Ramayana', 'Manu Kanunları'], 'Bhagavad Gita (\'Tanrı\'nın Ezgisi\'), Krişna ile Arjuna arasındaki konuşmayı içerir ve Hinduizmin en çok okunan metinlerinden biridir.'),
  ('Hindular için en kutsal şehirlerden biri sayılan ve Ganj kıyısındaki basamaklarda (ghat) ölülerin yakıldığı şehir hangisidir?', 'Varanasi', ['Mumbai', 'Amritsar', 'Bodh Gaya'], 'Varanasi (Benares), Şiva\'nın şehri sayılır; Hindular burada ölüp yakılmanın yeniden doğuş döngüsünden kurtuluşa yardım ettiğine inanır.'),
  ('Bir Hindu kadın evindeki küçük sunakta bir tanrı tasvirinin önüne çiçek, meyve ve yanan bir kandil koyup tütsü yakarak dua ediyor. Bu ibadetin adı nedir?', 'Puja', ['Mantra', 'Yoga', 'Sadhu'], 'Puja, evde ya da tapınakta tanrı tasvirine sunular sunularak yapılan ibadettir.'),
  ('Meditasyon yapan bir keşiş, zihnini odaklamak için \'Om mani padme hum\' sözlerini defalarca tekrar ediyor. Tekrarlanan bu kutsal söz dizisine ne ad verilir?', 'Mantra', ['Mandala', 'Mudra', 'Puja'], 'Mantra, tekrarlanarak zihni odaklayan kutsal ses ya da sözdür; \'Om\' en bilinen mantradır.'),
  ('Varanasi\'de turuncu giysili, uzun saçlı ve sakallı bir adam, mülkü ve ailesi olmadan yalnız sadakayla yaşayıp tapınaktan tapınağa dolaşıyor. Hint geleneğinde böyle çilecilere ne ad verilir?', 'Sadhu', ['Brahmin', 'Guru', 'Raja'], 'Sadhu, aile ve mülkten vazgeçerek manevi kurtuluşa adanmış bir yaşam süren gezgin çilecidir.'),
  ('Hinduizmde ineğin kutsal sayılmasının günlük yaşamdaki yansıması hangisidir?', 'Hinduların çoğunun sığır eti yememesi', ['İneklerin yalnız tapınaklarda yaşayabilmesi', 'Sütün dinen yasak sayılması', 'İnek derisinin kutsal kitapların kapağı olarak kullanılması'], 'Hinduizmde inek cömertlik ve annelik simgesi olarak kutsal sayılır; bu nedenle Hinduların büyük bölümü sığır eti yemez, süt ürünleri ise yaygın olarak tüketilir.'),
  ('\'Buda\' unvanı ne anlama gelir?', 'Uyanmış, aydınlanmış kişi', ['Kral oğlu', 'Dağda yaşayan çileci keşiş', 'Bilge öğretmen'], 'Buda, Sanskritçe \'budh\' (uyanmak) kökünden gelir ve \'uyanmış olan\' demektir; bir kişi adı değil, bir unvandır.'),
  ('Buda\'nın bir incir ağacının (Bodhi ağacı) altında aydınlandığı kabul edilen yer hangisidir?', 'Bodh Gaya', ['Lumbini', 'Sarnath', 'Kuşinagar'], 'Bodh Gaya, Hindistan\'ın Bihar eyaletindedir; Mahabodhi Tapınağı aydınlanmanın gerçekleştiği yeri işaret eder.'),
  ('Buda\'nın hem aşırı lüksü hem de aşırı çileciliği reddederek önerdiği yaşam yoluna ne ad verilir?', 'Orta Yol', ['Sessiz Yol', 'Yüksek Yol', 'Dar Yol'], 'Siddhartha sarayda lüksü, sonra yıllarca aşırı çileciliği denemiş; ikisinin de kurtuluşa götürmediğini görerek Orta Yol\'u önermiştir.'),
  ('Budizmin \'Dört Yüce Gerçek\' öğretisinin ilk gerçeği hangisidir?', 'Yaşamın acı (dukkha) içerdiği', ['Acının sona erdirilebileceği', 'Acının kaynağının arzu olduğu', 'Sekiz dilimli yolun acıyı sona erdirdiği'], 'Dört Yüce Gerçek sırasıyla acının varlığı, acının nedeni (arzu ve bağlanma), acının sona erebileceği ve bunun yolunu (Sekiz Dilimli Yol) anlatır.'),
  ('Bir Budist öğretmen, \'Bir mum alevi yakıtı bitince nasıl sönerse, arzu, nefret ve yanılgı da sönünce yeniden doğuş sona erer.\' diyor. Öğretmenin anlattığı durum hangisidir?', 'Nirvana', ['Samsara', 'Karma', 'Dharma'], 'Nirvana \'sönme\' anlamına gelir; arzu, nefret ve yanılgı ateşlerinin sönmesiyle ulaşılan kurtuluştur.'),
  ('Budizme yeni giren bir kişi bir tören sırasında \'Buda\'ya sığınırım, Dharma\'ya sığınırım, Sangha\'ya sığınırım\' diyor. Bu sözlerde sığınılan üç unsur hangi kavramı oluşturur ve nelerdir?', 'Üç Mücevher: Buda, öğreti ve keşiş topluluğu', ['Trimurti: Brahma, Vişnu ve Şiva', 'Üç Sepet: kurallar, vaazlar ve felsefi açıklamalar', 'Üç Zehir: arzu, nefret ve yanılgı'], 'Bir Budist, Buda\'ya, onun öğretisine (Dharma) ve keşiş topluluğuna (Sangha) sığınarak inancını ilan eder.'),
  ('Çin, Kore, Japonya ve Vietnam\'da yaygın olan, \'Büyük Taşıt\' anlamına gelen Budist gelenek hangisidir?', 'Mahayana', ['Theravada', 'Hinayana', 'Jodo'], 'Mahayana Budizmi, herkesin kurtuluşu için çalışan bodhisattva idealini öne çıkarır ve Doğu Asya\'da yaygınlaşmıştır.'),
  ('Bir Budist anlatıda, aydınlanmanın eşiğine gelen bir varlık acı çeken tüm canlılar kurtulmadan nirvanaya girmeyeceğine yemin ediyor. Mahayana Budizminde bu ideali temsil eden varlığa ne ad verilir?', 'Bodhisattva', ['Arhat', 'Lama', 'Sadhu'], 'Bodhisattva, merhamet nedeniyle tüm canlıların kurtuluşuna yardım etmeyi amaçlayan aydınlanmaya adanmış varlıktır; Theravada\'da ideal kişi daha çok arhattır.'),
  ('Kyoto\'daki bir manastırda keşişler saatlerce sessizce oturarak meditasyon yapıyor ve öğretmenleri onlara \'Tek elin çıkardığı ses nedir?\' gibi sorular soruyor. Bu manastır hangi Budist okula bağlıdır?', 'Zen', ['Theravada', 'Vajrayana', 'Jainizm'], 'Zen, Çin\'deki Chan okulunun Japonya\'daki biçimidir; \'Tek elin çıkardığı ses nedir?\' gibi koanlar mantıksal düşünceyi aşmayı amaçlar.'),
  ('Sanchi\'yi ziyaret eden bir gezgin, içinde kutsal kalıntıların saklandığı, yarım küre biçimli ve çevresinde tavaf yolu bulunan büyük bir anıt görüyor. Bu yapı türünün adı nedir?', 'Stupa', ['Pagoda', 'Jinja', 'Gurdwara'], 'Stupa, kutsal kalıntıları barındıran yarım küre biçimli anıttır; Sanchi Stupası en bilinen örneklerdendir. Doğu Asya\'daki çok katlı pagodalar bu formdan gelişmiştir.'),
  ('Sihizmin kurucusu kimdir?', 'Guru Nanak', ['Guru Gobind Singh', 'Kabir', 'Mahavira'], 'Guru Nanak (1469-1539) Pencap\'ta doğmuş ve Sihizmi kurmuştur; ardından dokuz guru daha gelmiştir.'),
  ('Sihlerin en kutsal mekânı sayılan Altın Tapınak (Harmandir Sahib) hangi şehirdedir?', 'Amritsar', ['Varanasi', 'Delhi', 'Lahor'], 'Altın Tapınak, Pencap\'taki Amritsar\'da yapay bir göl ortasında yer alır; dört yöne açılan kapıları herkese açık olmayı simgeler.'),
  ('Sihizmin temel öğretileri arasında aşağıdakilerden hangisi yer alır?', 'Tek Tanrı inancı ve kast ayrımının reddi', ['Çok tanrılı tapınma ve kast düzeni', 'Keşişlik ve evlilikten kaçınma', 'Hayvan kurbanının zorunluluğu'], 'Sihizm tek Tanrı\'ya inanır, kast ayrımını reddeder ve keşişlik yerine aile içinde dürüst çalışma ile paylaşmayı öğütler.'),
  ('Sihlerin ibadet ettiği tapınağa ne ad verilir?', 'Gurdwara', ['Mandir', 'Pagoda', 'Ateşkede'], 'Gurdwara \'gurunun kapısı\' demektir; içinde Guru Granth Sahib bulunur ve herkese açıktır.'),
  ('Çinli bir genç, yaşlanan anne babasına bakmak için şehirdeki işini bırakıp köyüne dönüyor ve atalarının mezarlarını düzenli ziyaret ediyor. Bu davranış Konfüçyüsçülüğün hangi erdemini yansıtır?', 'Xiao', ['Wu wei', 'Yin', 'Zen'], 'Xiao (hsiao), evlat saygısı ve bağlılığıdır; aile düzeninin ve buna bağlı olarak toplum düzeninin temeli sayılır.'),
  ('Taoizmin temel metni olan ve geleneksel olarak Laozi\'ye atfedilen eser hangisidir?', 'Tao Te Ching', ['Analektler', 'I Ching', 'Lotus Sutra'], 'Tao Te Ching (\'Yol ve Erdem Kitabı\') kısa şiirsel bölümlerden oluşur ve Taoizmin temel metnidir.'),
  ('Bir Taoist öğretmen öğrencisine \'Su engelle karşılaşınca onunla savaşmaz, etrafından dolaşır ve sonunda taşı aşındırır.\' diyor. Bu benzetme Taoizmin hangi kavramını anlatır?', 'Wu wei', ['Ren', 'Xiao', 'Li'], 'Wu wei \'eylemsiz eylem\' olarak çevrilir; suyun engellerin etrafından akması gibi zorlamadan hareket etmeyi öğütler.'),
  ('Taoist düşüncede birbirine karşıt ama birbirini tamamlayan iki gücü simgeleyen kavram çifti hangisidir?', 'Yin ve yang', ['Ren ve li', 'Karma ve samsara', 'Atman ve Brahman'], 'Yin karanlık, dişil ve edilgen; yang aydınlık, eril ve etkin yönü simgeler. İkisi birbirine dönüşerek dengeyi sağlar.'),
  ('Japonya\'da bir köy halkı, eski bir şelalenin, dağın ve atalarının ruhlarının kutsal varlıklar olduğuna inanıp onlar için küçük tapınaklar kuruyor. Şintoda bu kutsal varlıklara ne ad verilir?', 'Kami', ['Buda', 'Deva', 'Orisha'], 'Kami; doğa güçleri, dağlar, ağaçlar, atalar ve olağanüstü kişiler gibi kutsal sayılan varlıklardır.'),
  ('Kyoto\'daki Fuşimi İnari Tapınağı\'nda ziyaretçiler, dağ yamacı boyunca dizilmiş binlerce turuncu, iki direkli ve üstü kirişli kapının altından geçiyor. Bu kapıların adı nedir?', 'Torii', ['Pagoda', 'Stupa', 'Gopuram'], 'Torii, gündelik dünyadan kutsal alana geçişi simgeleyen kapıdır; çoğu kırmızı-turuncu renge boyanır.'),
  ('Sibirya\'da bir köyde hastalanan birini iyileştirmek için davul çalan, transa geçen ve ruhlarla konuştuğuna inanılan bir din adamı tören yapıyor. Bu kişiye ne ad verilir?', 'Şaman', ['Brahmin', 'Lama', 'Mobed'], 'Şaman sözcüğü Sibirya\'daki Tunguz (Evenk) dilinden gelir; Türk boylarında bu kişiye \'kam\' denirdi.'),
  ('Avustralya\'da Aborjinlerce kutsal sayılan dev kumtaşı kütlesi hangisidir?', 'Uluru', ['Kilimanjaro', 'Fuji', 'Kailaş'], 'Uluru (Ayers Rock), Anangu halkı için kutsaldır; 2019\'dan beri üzerine tırmanmak yasaktır.'),
  ('Hristiyan geleneğine göre İsa\'nın çarmıha gerildiği ve gömüldüğü yerin üzerine yapılmış olan Kudüs\'teki kilise hangisidir?', 'Kutsal Kabir Kilisesi', ['Doğuş Kilisesi', 'Aziz Petrus Bazilikası', 'Ayasofya'], 'Kutsal Kabir Kilisesi (Kıyamet Kilisesi), 4. yüzyılda I. Konstantin döneminde yaptırılmış; birden çok Hristiyan cemaati tarafından ortak kullanılır.'),
  ('Hristiyan geleneğinde İsa\'nın doğduğu kabul edilen ve Doğuş Kilisesi\'nin bulunduğu şehir hangisidir?', 'Beytüllahim', ['Nasıra', 'Kefernahum', 'Eriha'], 'Beytüllahim (Bethlehem), İnciller\'e göre İsa\'nın doğduğu şehirdir; Doğuş Kilisesi dünyanın sürekli kullanılan en eski kiliselerindendir.'),
  ('Fransa\'da 1858\'de Bernadette Soubirous\'un Meryem\'i gördüğünü anlattığı ve şifa beklentisiyle milyonlarca Katolik\'in ziyaret ettiği hac yeri hangisidir?', 'Lourdes', ['Fatima', 'Santiago de Compostela', 'Assisi'], 'Lourdes\'daki mağara ve kaynak, Katolik dünyasının en çok ziyaret edilen hac yerlerindendir.'),
  ('İslam\'da Mescid-i Haram ve Mescid-i Nebevi\'den sonra en kutsal üçüncü mescit sayılan yapı hangi şehirdedir?', 'Kudüs', ['Şam', 'Kahire', 'Bağdat'], 'Mescid-i Aksa Kudüs\'tedir; hadislerde ziyaret için yolculuk yapılacak üç mescitten biri olarak anılır.'),
  ('Hz. Muhammed\'in kabrinin bulunduğu mescit hangisidir?', 'Mescid-i Nebevi', ['Mescid-i Haram', 'Kuba Mescidi', 'Mescid-i Aksa'], 'Medine\'deki Mescid-i Nebevi, Hz. Muhammed\'in yaptırdığı ve kabrinin içinde yer aldığı mescittir.'),
  ('Bir kişi, miras paylaşımıyla ilgili bir konuda dinî hükmü öğrenmek için ilindeki din görevlisine başvuruyor ve yazılı bir görüş alıyor. Bu görüşü veren yetkili kimdir?', 'Müftü', ['Müezzin', 'Hafız', 'Kayyum'], 'Müftü, dinî konularda fetva (görüş) verme yetkisi olan âlimdir; Türkiye\'de il ve ilçe müftüleri Diyanet İşleri Başkanlığı\'na bağlıdır.'),
  ('Bir Yahudi aile, düğünlerini yönetmesi ve Şabat kurallarıyla ilgili bir sorularına yanıt vermesi için cemaatlerinin dinî önderine başvuruyor. Bu din adamına ne ad verilir?', 'Haham (rabbi)', ['Kantor', 'Levili (tapınak görevlisi)', 'Kohen'], 'Haham (rabbi) \'öğretmenim\' anlamına gelir; topluluğa dinî rehberlik eder ve hukuki sorulara yanıt verir.'),
  ('Tibet Budizminde öğretmen ya da manevi usta anlamına gelen unvan hangisidir?', 'Lama', ['Guru Granth', 'Mobed', 'Rinzai'], 'Lama, Sanskritçe \'guru\' sözcüğünün Tibetçe karşılığıdır; saygın Budist öğretmenlere verilen unvandır.'),
  ('Bir gezgin İstanbul\'da bir caminin çevresinde medrese, aşevi, hastane, hamam ve kütüphanenin tek bir plan içinde birlikte yapıldığını görüyor. Bu yapı topluluğuna ne ad verilir?', 'Külliye', ['Kervansaray', 'Bedesten', 'Arasta'], 'Külliye, cami merkezli olarak eğitim, sağlık ve sosyal hizmet yapılarını bir araya getiren yapı topluluğudur; Süleymaniye Külliyesi bunun bilinen örneğidir.'),
  ('Bir ibadethane, içinde imamın namaz kıldırdığı bir niş, avluda abdest için şadırvan ve yüksek bir kule barındırıyor. Bu yapı hangi dine aittir?', 'İslam', ['Yahudilik', 'Sihizm', 'Şinto'], 'Mihrap, şadırvan ve minare cami mimarisinin temel öğeleridir.'),
  ('Erken Hristiyanların gizli bir tanıtım işareti olarak kullandığı ve Yunanca adı \'İsa Mesih, Tanrı\'nın Oğlu, Kurtarıcı\' sözlerinin baş harflerinden oluşan simge hangisidir?', 'Balık', ['Kuzu', 'Güvercin', 'Çapa'], 'Yunanca \'balık\' anlamındaki ikhthys sözcüğünün harfleri bu ifadenin baş harflerine karşılık gelir; zulüm döneminde gizli bir işaret olarak kullanılmıştır.'),
  ('Hindu ve Budist geleneklerde kutsal ses olarak kabul edilen ve Devanagari yazısıyla simgeleştirilen hece hangisidir?', 'Om', ['Amin', 'Şalom', 'Namaste'], 'Om, evrenin özünü simgelediğine inanılan kutsal hecedir; mantra ve duaların başında ve sonunda okunur.'),
  ('Budist ve Hindu sanatında çamurlu sudan temiz ve güzel çiçek açan yapısıyla saflığı ve aydınlanmayı simgeleyen bitki hangisidir?', 'Lotus', ['Gül', 'Zeytin', 'Selvi ağacı'], 'Lotus çamurda kök salıp suyun üstünde lekesiz açtığı için zihnin dünya kirlerinden arınmasını simgeler; Buda çoğu zaman lotus üzerinde tasvir edilir.'),
  ('Yeni Ahit\'teki Elçilerin İşleri kitabına göre İsa\'nın izleyicilerine ilk kez \'Hristiyan\' adının verildiği şehir hangisidir?', 'Antakya', ['Kudüs', 'Roma', 'Efes'], 'Elçilerin İşleri 11:26\'ya göre öğrencilere ilk kez Antakya\'da Hristiyan denmiştir; Antakya\'daki Aziz Petrus Mağara Kilisesi erken dönemin simgelerindendir.'),
  ('Efes yakınlarındaki Bülbül Dağı\'nda bulunan ve Hristiyan geleneğinde Meryem\'in son yıllarını geçirdiğine inanılan yer hangisidir?', 'Meryem Ana Evi', ['Yedi Uyurlar Mağarası', 'Aziz Yuhanna Bazilikası', 'Sardes Sinagogu'], 'Meryem Ana Evi hem Hristiyanlar hem de Müslümanlar tarafından ziyaret edilir; birçok papa da burayı ziyaret etmiştir.'),
  ('Trabzon\'un Maçka ilçesinde sarp bir kayalığa oyulmuş olarak yapılan ve Meryem\'e adanmış Rum Ortodoks manastırı hangisidir?', 'Sümela Manastırı', ['Mor Gabriel Manastırı', 'Ahtamar Kilisesi', 'Aziz Nikolaos Kilisesi'], 'Sümela (Panagia Sumela) Manastırı, Altındere Vadisi\'nde 1200 metre yükseklikteki kayalığa yapılmıştır.'),
  ('İslam\'ı devlet dini olarak kabul eden ilk Türk devleti hangisidir?', 'Karahanlılar', ['Gazneliler', 'Büyük Selçuklular', 'Tolunoğulları'], 'Karahanlı hükümdarı Satuk Buğra Han\'ın 10. yüzyılda Müslüman olmasının ardından İslam devletin resmî dini hâline gelmiştir.'),
  ('Selçuklu ve Osmanlı döneminde dinî eğitim veren yükseköğretim kurumlarına ne ad verilirdi?', 'Medrese', ['Mektep', 'Enderun', 'Darülfünun'], 'Medreseler tefsir, hadis, fıkıh, kelam gibi dinî ilimlerin yanında dil ve akli ilimlerin de okutulduğu kurumlardı; Nizamiye Medreseleri bu modelin öncülerindendir.'),
  ('Bir tüccar, sahip olduğu dükkânların kira gelirinin sonsuza dek mahallesindeki çeşmenin bakımına ve yoksul öğrencilerin yemeğine harcanmasını şart koşan bir belge düzenliyor. Tüccarın kurduğu kurum hangisidir?', 'Vakıf', ['Lonca', 'Ahilik', 'Kervan'], 'Vakıf, mülkün özel mülkiyetten çıkarılıp gelirinin belirlenen hayır amacına süresiz olarak harcanmasıdır.'),
  ('Bir ilahiyat öğrencisi tezinde farklı dinlerin kıyamet, son yargı, cennet ve cehennem hakkındaki öğretilerini karşılaştırıyor. Öğrencinin çalıştığı alan hangisidir?', 'Eskatoloji', ['Kozmogoni', 'Teodise', 'Hermenötik'], 'Eskatoloji, Yunanca \'son\' anlamındaki eskhatos sözcüğünden gelir ve son şeylere dair öğretiyi anlatır.'),
  ('Katolik, Ortodoks ve Protestan kiliselerinin temsilcileri ortak bir duada buluşuyor ve kiliseler arası birliği güçlendirmek için bildiri yayımlıyor. Bu çabalar hangi hareketin parçasıdır?', 'Ekümenizm', ['Senkretizm', 'Misyonerlik', 'Monastisizm'], 'Ekümenizm, Yunanca \'meskûn dünya\' anlamındaki oikoumene\'den gelir; 1948\'de kurulan Dünya Kiliseler Konseyi bu hareketin en önemli kurumudur.'),
  ('19. yüzyılda bir Avrupa kilise derneği, Afrika ve Asya\'da okullar, hastaneler açıp Hristiyanlığı tanıtmak için din görevlileri gönderiyor. Bu tür faaliyetlere ne ad verilir?', 'Misyonerlik', ['Ekümenizm', 'Senkretizm', 'İnziva'], 'Misyonerlik, bir inancı yaymak amacıyla yapılan örgütlü çalışmadır; 16. yüzyılda Cizvitler, 19. yüzyılda Protestan misyon dernekleri bu alanda etkili olmuştur.'),
  ('Bir sosyolog, bir ülkede kiliseye düzenli gidenlerin oranının on yıllar içinde azaldığını, evliliklerin ve eğitimin büyük ölçüde dinî kurumların dışına çıktığını gözlemliyor. Bu süreç hangi kavramla açıklanır?', 'Sekülerleşme', ['Senkretizm', 'Ekümenizm', 'Misyonerlik faaliyeti'], 'Sekülerleşme, dinin kamusal alandaki ve bireylerin hayatındaki belirleyiciliğinin azalmasını anlatan sosyolojik kavramdır.'),
  ('Bir din adamının ya da topluluğun, dünyadan uzaklaşarak ibadet ve tefekkürle yaşamak için yalnızlığa çekilmesine genel olarak ne ad verilir?', 'İnziva', ['Hac', 'Misyon', 'Vaaz'], 'İnziva, Hristiyan keşişlerinde, sufi çilesinde ve Hindu-Budist çilecilerde görülen ortak bir dinî uygulamadır.'),
  ('Bir kilisede rahip, yetişkin bir adayı suyla dolu bir havuza tamamen batırıp çıkarıyor ve onu Hristiyan topluluğuna kabul ediyor. Bu ritüel hangisidir?', 'Vaftiz', ['Komünyon', 'Konfirmasyon', 'Kutsama'], 'Vaftiz, Hristiyanlığa girişin sakramentidir; bazı kiliseler bebekleri, Baptistler gibi bazıları ise inancını ilan eden yetişkinleri vaftiz eder.'),
  ('Hristiyan ayininde ekmek ve şarabın İsa\'nın son akşam yemeğini anarak paylaşılmasına ne ad verilir?', 'Komünyon', ['Vaftiz', 'Konfirmasyon', 'Ekskomünikasyon'], 'Komünyon, İsa\'nın son akşam yemeğinde ekmek ve şarap paylaşmasını anan merkezî Hristiyan ayinidir; Katoliklikte Efkaristiya olarak da anılır.'),
  ('Bir aile, ağır bir ameliyat öncesinde dinî inançları nedeniyle kan nakline izin vermiyor; aynı topluluğun üyeleri kapı kapı dolaşarak dergi dağıtmalarıyla da tanınıyor. Bu topluluk hangisidir?', 'Yehova Şahitleri', ['Mormonlar', 'Adventistler', 'Metodistler'], 'Yehova Şahitleri, Charles Taze Russell\'ın başlattığı İncil Tetkikçileri hareketinden gelişmiştir; kan naklini dinî gerekçelerle reddederler.'),
  ('Bir Benedikten manastırında keşişler, çalgı kullanmadan, hep birlikte aynı ezgiyi tek sesle ve Latince söylüyor. Dinledikleri müzik geleneğinin adı nedir?', 'Gregoryen ilahisi', ['Gospel', 'Oratoryo', 'Kantat'], 'Gregoryen ilahisi adını Papa I. Gregorius\'tan alır; tek sesli ve serbest ritimli Latince ayin müziğidir.'),
  ('Chicago\'daki bir kilisede geniş bir koro el çırparak, coşkulu bir ritimle ve solistin sesine karşılık vererek İsa\'yı öven şarkılar söylüyor. Bu müzik türünün adı nedir?', 'Gospel', ['Gregoryen ilahisi', 'Madrigal', 'Rekuiem'], 'Gospel (\'müjde\') müziği, Afrikalı Amerikalıların spiritual geleneğinden gelişmiş ve blues, caz ve soul müziğini de etkilemiştir.'),
  ('Bir Müslüman, bir yemeğin içinde domuz yağı bulunduğunu öğrenince onu yemekten vazgeçiyor. İslam\'da bu yiyeceğin dinî durumu nasıl nitelenir?', 'Haram', ['Helal', 'Mekruh', 'Mübah'], 'Haram dinen kesin olarak yasak olanı, helal ise izin verileni anlatır; mekruh hoş görülmeyen, mübah ise serbest bırakılan anlamındadır.'),
  ('Rum Ortodoks bir aile büyük perhiz döneminde sofrasını hazırlıyor. Geleneğe uygun olarak bu dönemde sofraya hangi yiyecekler konmaz?', 'Et, süt ürünleri ve yumurtadan', ['Yalnız ekmekten', 'Sebze, meyve ve baklagillerden', 'Yalnız sudan'], 'Ortodoks perhizlerinde genellikle et, süt ürünleri ve yumurta yenmez; bazı günlerde balık, yağ ve şarap da kısıtlanır.'),
  ('Bir otel mutfağı aynı akşam yemeğinde Müslüman, Yahudi ve Hindu konuklara hizmet verecek. Her üç grubun dinî kurallarına aynı anda en kolay uyan ana yemek hangisidir?', 'Sebzeli pirinç pilavı', ['Domuz pirzola', 'Sığır eti yahnisi', 'Tereyağlı tavuk ve peynir soslu makarna'], 'Domuz eti İslam ve Yahudilikte yasaktır; sığır eti çoğu Hindu tarafından yenmez; et ile süt ürünü bir arada kaşrut kurallarına aykırıdır. Sebzeli pilav üç grubun kurallarına da uyar.'),
  ('Bir âlim, alışverişte kusurlu malın iadesi, miras paylaşımı ve namazın geçerlilik koşulları gibi konularda hüküm çıkarmak için Kur\'an ve sünneti inceliyor. Bu âlimin uğraştığı ilim dalı hangisidir?', 'Fıkıh', ['Kelam', 'Tefsir', 'Tasavvuf'], 'Fıkıh, Kur\'an, sünnet, icma ve kıyas gibi kaynaklardan ameli hükümler çıkaran ilimdir; bu hükümleri çıkaran âlime müçtehit denir.'),
  ('\'Gelin tanış olalım, işi kolay kılalım\' dizeleriyle bilinen ve sade Türkçesiyle tasavvufi düşünceyi halka ulaştıran 13-14. yüzyıl şairi kimdir?', 'Yunus Emre', ['Ahmed Yesevi', 'Pir Sultan Abdal', 'Kaygusuz Abdal'], 'Yunus Emre, Anadolu\'da Türkçe tasavvuf şiirinin en büyük temsilcisidir; sevgi, hoşgörü ve insan sevgisini işleyen şiirleri ilahiler olarak da okunur.'),
  ('İslam\'da dinî bir konuda yetkin bir âlimin sorulan soruya verdiği yanıta ne ad verilir?', 'Fetva', ['Hutbe', 'Hadis', 'Ferman'], 'Fetva, müftünün dinî bir soruya verdiği görüştür; Osmanlı\'da şeyhülislam fetvaları önemli kararlarda başvurulan belgelerdi.'),
  ('Tevrat\'ın Çıkış kitabına göre İsrailoğullarını Mısır\'dan çıkaran peygamber kimdir?', 'Musa', ['İbrahim', 'Yusuf', 'Davud'], 'Çıkış (Exodus) kitabı, Musa\'nın önderliğinde İsrailoğullarının Mısır\'daki kölelikten kurtuluşunu anlatır.'),
  ('Hristiyanlıkta İsa\'nın annesi Meryem\'in bakire olarak doğurduğu inancı hangi kavramla anlatılır?', 'Bakireden doğum', ['Enkarnasyon', 'Kefaret', 'Göğe yükseliş'], 'Matta ve Luka İncilleri İsa\'nın bakire Meryem\'den doğduğunu anlatır; İslam\'da da Hz. Meryem\'in İsa\'yı babasız doğurduğu kabul edilir.'),
  ('Hristiyan geleneğinde gururdan oburluğa kadar sıralanan \'yedi ölümcül günah\' listesinde aşağıdakilerden hangisi yer alır?', 'Kıskançlık', ['Cömertlik', 'Alçakgönüllülük', 'Sabır'], 'Yedi ölümcül günah kibir, açgözlülük, şehvet, kıskançlık, oburluk, öfke ve tembelliktir.'),
  ('Şanlıurfa\'daki Balıklıgöl, hangi peygamberle ilgili anlatı nedeniyle kutsal sayılır?', 'Hz. İbrahim\'in Nemrut tarafından ateşe atılması', ['Hz. Nuh\'un gemisinin karaya oturması', 'Hz. Musa\'nın denizi yarması', 'Hz. Yunus\'un balık tarafından yutulması'], 'Halk anlatısına göre Nemrut\'un İbrahim\'i attığı ateş suya, odunlar balığa dönüşmüştür; bu nedenle göldeki balıklar kutsal sayılır.'),
  ('Bir gezgin sırasıyla Amritsar, Bodh Gaya ve Varanasi\'yi ziyaret ediyor. Bu şehirler hangi dinlerin kutsal mekânlarıdır?', 'Sihizm, Budizm, Hinduizm', ['Hinduizm, Caynizm, Sihizm', 'Budizm, Sihizm, Caynizm', 'Caynizm, Hinduizm, Budizm'], 'Amritsar\'daki Altın Tapınak Sihlerin, Bodh Gaya Budistlerin, Varanasi ise Hinduların en kutsal mekânlarındandır.'),
  ('Aşağıdaki ibadethane-din eşleştirmelerinden hangisi doğrudur?', 'Jinja - Şinto', ['Gurdwara - Hinduizm', 'Sinagog - Zerdüştlük', 'Mandir - Sihizm'], 'Jinja Şinto tapınağıdır; gurdwara Sihlerin, sinagog Yahudilerin, mandir ise Hinduların ibadethanesidir.'),
  ('Bir belgeselde bir din adamının turuncu-safran rengi cüppe giyip başını kazıttığı, sabahları kâse ile yiyecek topladığı anlatılıyor. Bu din adamı büyük olasılıkla hangi geleneğe aittir?', 'Theravada Budizmi', ['Ortodoks Hristiyanlık', 'Sihizm', 'Zerdüştlük'], 'Safran renkli cüppe, kazınmış baş ve sadaka kâsesiyle yiyecek toplama Theravada Budist keşişlerinin belirgin özellikleridir.'),
  ('Bizans İmparatoru I. Justinianus\'un yaptırdığı ve 537\'de açılan Ayasofya hangi amaçla inşa edilmişti?', 'İmparatorluğun ana katedrali olarak', ['Bir saray salonu olarak', 'Bir kütüphane olarak', 'Bir hipodrom tribünü olarak'], 'Ayasofya (\'Kutsal Bilgelik\'), Bizans\'ın en önemli katedrali olarak yapılmış; imparatorların taç giyme törenleri burada gerçekleşmiştir.'),
  ('Ramazan boyunca her gün bir cüz okuyan bir kişi, ayın sonunda 30. cüzü de bitirerek Kur\'an\'ın tamamını okumuş oluyor. Bu işin adı nedir?', 'Hatim', ['Mukabele', 'Tecvit', 'Cüz'], 'Hatim, Kur\'an\'ı baştan sona okumaktır; Ramazan\'da camilerde hafızın okuyup cemaatin takip ettiği okumaya mukabele denir.'),
  ('Kur\'an\'daki surelerin başında, Tevbe suresi dışında yer alan \'Bismillahirrahmanirrahim\' ifadesine ne ad verilir?', 'Besmele', ['Kelime-i tevhit', 'Tekbir', 'Salavat'], 'Besmele \'Rahman ve Rahim olan Allah\'ın adıyla\' anlamına gelir; Müslümanlar birçok işe besmeleyle başlar.'),
  ('İslam\'da \'Allahu ekber\' sözüne ne ad verilir?', 'Tekbir', ['Besmele', 'Tehlil', 'Salavat'], 'Tekbir \'Allah en büyüktür\' anlamına gelir; ezanın ve namazın temel sözlerindendir.'),
  ('Cuma günü öğle vakti camide cemaatle kılınan cuma namazının yerini aldığı vakit namazı hangisidir?', 'Öğle namazı', ['Sabah namazı', 'İkindi namazı', 'Akşam namazı'], 'Cuma namazı öğle vaktinde kılınır ve o günün öğle namazının yerine geçer.'),
  ('Ramazan\'ın ilk gecesinde camiye giden bir kişi, yatsı namazından sonra cemaatin uzun bir namaz daha kıldığını görüyor. Ramazan gecelerine özgü bu namazın adı nedir?', 'Teravih', ['Teheccüt', 'Duha', 'Vitir'], 'Teravih, Ramazan gecelerinde yatsıdan sonra kılınan namazdır; Türkiye\'de genellikle yirmi rekât kılınır.'),
  ('Ameliyat nedeniyle öğle namazını vaktinde kılamayan bir hasta, iyileşince bu namazı sonradan kılıyor. Bu şekilde kılınan namaza ne denir?', 'Kaza', ['Eda', 'Nafile', 'Vitir'], 'Vaktinde kılınan namaza eda, vakti geçtikten sonra kılınan namaza kaza denir.'),
  ('Taoizme adını veren \'Tao\' (Dao) sözcüğü Çincede temel olarak ne anlama gelir?', 'Yol', ['Işık', 'Su', 'Gökyüzü'], 'Tao \'yol\' demektir; Taoizmde evrenin adlandırılamayan temel ilkesini ve doğal düzenini anlatır.'),
  ('Ortaçağ Avrupası\'nda Kudüs\'ü ve kutsal toprakları ele geçirmek için düzenlenen ve din adına yapılan sefer dizisi hangi adla bilinir?', 'Haçlı Seferleri', ['Reconquista', 'Otuz Yıl Savaşları', 'Yüzyıl Savaşları'], '1096\'da başlayan Haçlı Seferleri, papalığın çağrısıyla Kudüs\'ü almak amacıyla düzenlenmiştir; 1099\'da Kudüs alınmış, 1187\'de Selahaddin Eyyubi tarafından geri alınmıştır.'),
  ('Aşağıdaki kişilerden hangisi kronolojik olarak en erken yaşamıştır?', 'Buda', ['Hz. Muhammed', 'Guru Nanak', 'Martin Luther'], 'Buda MÖ 6-5. yüzyılda, Hz. Muhammed 6-7. yüzyılda, Guru Nanak 15-16. yüzyılda, Luther ise 15-16. yüzyılda yaşamıştır.'),
  ('Bir sınıf tartışmasında \'Tüm Hristiyanlar papaya bağlıdır\' deniyor. Bu yargının neden yanlış olduğunu en iyi açıklayan bilgi hangisidir?', 'Ortodoks, Protestan ve Doğu kiliseleri papanın otoritesini tanımaz', ['Papa yalnız İtalya\'daki kiliseleri yönetir', 'Papalık 20. yüzyılda kaldırılmıştır', 'Katolikler de papaya bağlı değildir'], 'Papaya bağlı olan yalnız Katolik Kilisesi\'dir; Ortodoks kiliseler, Protestan kiliseler ve Kıpti, Ermeni gibi Doğu kiliseleri papanın yetkisini kabul etmez.'),
  ('Bir öğrenci \'Bütün Müslümanlar aynı mezhebe bağlıdır\' diyor. Bu genellemeyi çürüten en doğrudan örnek hangisidir?', 'İslam dünyasında Sünni ve Şii gibi farklı mezheplerin bulunması', ['Müslümanların tamamının Arapça konuşması', 'Bütün Müslümanların Mekke\'de yaşaması', 'Kur\'an\'ın birden çok farklı metninin bulunması'], 'Sünnilik ve Şiilik ile bunların içindeki Hanefi, Şafii, Caferi, İsmaili gibi kollar İslam\'ın tek bir mezhepten oluşmadığını gösterir.'),
  ('Bir camide namaz vakti girince bir görevli minareye ya da mikrofona geçerek ezanı okuyor. Bu görevlinin unvanı nedir?', 'Müezzin', ['İmam', 'Hatip', 'Vaiz'], 'Müezzin ezan ve kamet okur; imam namaz kıldırır, hatip hutbe okur, vaiz ise vaaz verir.'),
  ('Bir camide cuma günü imam minbere çıkıp topluluğa haftanın konusunu anlatan konuşmayı yapıyor. Hutbeyi okuyan kişi bu görevi yaparken hangi unvanla anılır?', 'Hatip', ['Müezzin', 'Kayyum', 'Hafız'], 'Hatip, cuma ve bayram hutbelerini okuyan görevlidir; büyük camilerde imam ve hatip görevleri çoğu zaman birleşir.'),
];
